draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw dog
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 15, H/2 + 40);
  ctx.stroke();

  // draw clock
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2 - 50, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 - 50);
  ctx.lineTo(W/2 - 70 + 25 * Math.sin(t), H/2 - 50 - 25 * Math.cos(t));
  ctx.stroke();

  // draw owner's chair
  ctx.beginPath();
  ctx.rect(W/2 + 50, H/2 - 20, 30, 40);
  ctx.stroke();

  // draw dog's waiting expression
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 + 10);
  ctx.lineTo(W/2 - 15, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 10, H/2 + 10);
  ctx.lineTo(W/2 + 15, H/2 + 20);
  ctx.stroke();

  ctx.restore();
}
